    if not occupied_rows:
        return out
    top, bottom = min(occupied_rows), max(occupied_rows)

    # Fill horizontal gaps on the upper/lower edges, and on rows containing
    # a continuous horizontal run of at least three markers.
    for r, positions in enumerate(row_marks):
        horizontal = r == top or r == bottom
        for a, b in zip(positions, positions[1:]):
