                horizontal = True
        if horizontal:
            for a, b in zip(positions, positions[1:]):
                for c in range(a + 1, b):
                    if out[r][c] == background:
                        out[r][c] = 2

    # Fill gaps between successive markers in each column.
    for c, positions in enumerate(col_marks):
        for a, b in zip(positions, positions[1:]):
            for r in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = 2

    return out
